namespace ghidra.app.plugin.core.datamgr.actions;



using ghidra.app.plugin.core.datamgr;
using ghidra.program.model.dtarchive;
using ghidra.util;

public class UndoArchiveTransactionAction : AbstractUndoRedoArchiveTransactionAction {

	public UndoArchiveTransactionAction(DataTypeManagerPlugin plugin) : base("Undo", plugin)
    {
		// Key-bind disabled by default to activation context concerns
		//setKeyBindingData(new KeyBindingData("ctrl Z"));
		setDescription("Undo last change made to data type archive");
	}

	/* @Override */
	protected bool canExecute(PersistentDataTypeArchive dta) {
		return dta.canUndo();
	}

	/* @Override */
	protected string getNextName(PersistentDataTypeArchive dta) {
		return dta.getUndoName();
	}

	/* @Override */
	protected void execute(PersistentDataTypeArchive dta) {
		try {
			dta.undo();
		}
		catch (IOException e) {
			Msg.showError(this, null, "Archive Undo Failed",
				"Failed to undo last transaction: " + dta.getName(), e);
		}
	}

}
